from pathlib import Path
targets = (
    'tools/session_logs/cli.py',
    'tools/session_logs/read_only_entry.py',
    'tools/session_logs/eventual_preservation.py',
)
for target in targets:
    print(target)
    for number, line in enumerate(
        Path(target).read_text(encoding='utf-8').splitlines(), start=1
    ):
        stripped = line.strip()
        if stripped.startswith('EXIT_') and '=' in stripped:
            print(' ', number, stripped)
